package com.catalogix.fulfillment.model;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="shipments",uniqueConstraints=@UniqueConstraint(name="uk_order_seller",columnNames={"order_id","seller_id"}))
public class Shipment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Version Long version; @Column(name="order_id",nullable=false) Long orderId; @Column(name="user_id",nullable=false) Long userId; @Column(name="seller_id",nullable=false) Long sellerId; @Column(name="tracking_number",nullable=false,unique=true) String trackingNumber; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) ShipmentStatus status=ShipmentStatus.CREATED; @Column(nullable=false,updatable=false) Instant createdAt=Instant.now(); @Column(nullable=false) Instant updatedAt=Instant.now(); public Long getId(){return id;} public Long getOrderId(){return orderId;} public Long getUserId(){return userId;} public Long getSellerId(){return sellerId;} public String getTrackingNumber(){return trackingNumber;} public ShipmentStatus getStatus(){return status;} public void setStatus(ShipmentStatus s){status=s;updatedAt=Instant.now();} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void setOrderId(Long v){orderId=v;} public void setUserId(Long v){userId=v;} public void setSellerId(Long v){sellerId=v;} public void setTrackingNumber(String v){trackingNumber=v;} }
